CREATE OR REPLACE FUNCTION private.account_removal_preview(p_actor uuid, p_kind text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE target uuid; profile public.profiles%rowtype; r jsonb;
BEGIN
 IF auth.role()<>'service_role' AND p_actor IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Actor identity mismatch' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=p_actor AND p.role='admin' AND NOT p.suspended AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF p_kind='vendor' THEN SELECT owner_id INTO target FROM public.vendors WHERE id=p_id; ELSIF p_kind='customer' THEN target:=p_id; ELSE RAISE EXCEPTION 'Invalid removal kind'; END IF;
 IF target IS NULL THEN RAISE EXCEPTION 'Account owner not found; requires manual review'; END IF;
 SELECT * INTO STRICT profile FROM public.profiles WHERE id=target;
 IF target=p_actor THEN RAISE EXCEPTION 'Self-removal is prohibited'; END IF;
 IF profile.role='admin' AND (SELECT count(*) FROM public.profiles WHERE role='admin' AND NOT suspended AND deleted_at IS NULL)<=1 THEN RAISE EXCEPTION 'Cannot remove last active administrator'; END IF;
 IF profile.role='admin' OR(p_kind='customer' AND profile.role<>'customer') THEN RAISE EXCEPTION 'Use an account type matching the designated record'; END IF;
 r:=jsonb_build_object('kind',p_kind,'recordId',p_id,'userId',target,'name',profile.name,'confirmation',p_kind||':'||p_id::text,
  'vendors',(SELECT coalesce(jsonb_agg(id),'[]') FROM public.vendors WHERE owner_id=target),
  'orders',(SELECT count(*) FROM public.orders WHERE customer_id=target OR id IN(SELECT order_id FROM public.order_suborders WHERE vendor_id IN(SELECT id FROM public.vendors WHERE owner_id=target))),
  'suborders',(SELECT count(*) FROM public.order_suborders WHERE vendor_id IN(SELECT id FROM public.vendors WHERE owner_id=target)),
  'meals',(SELECT count(*) FROM public.meals WHERE vendor_id IN(SELECT id FROM public.vendors WHERE owner_id=target)),
  'conversations',(SELECT count(*) FROM public.conversations WHERE customer_id=target OR vendor_id IN(SELECT id FROM public.vendors WHERE owner_id=target)),
  'notifications',(SELECT count(*) FROM public.notifications WHERE user_id=target),
  'storage',(SELECT coalesce(jsonb_agg(jsonb_build_object('bucket',bucket_id,'name',name) ORDER BY bucket_id,name),'[]') FROM storage.objects
    WHERE owner_id=target::text OR owner=target OR (bucket_id IN('meal-images','vendor-images') AND split_part(name,'/',1) IN(SELECT id::text FROM public.vendors WHERE owner_id=target))),
  'financialHistory','Retained. Vendor records are archived; profiles are anonymised. Auth identity is deleted only after Storage cleanup.');
 r:=r||jsonb_build_object('blockers',private.removal_blockers(target));
 RETURN r||jsonb_build_object('fingerprint',md5(r::text));
END $function$

CREATE OR REPLACE FUNCTION private.conversation_retention_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE removed integer; settings private.retention_settings%rowtype;
BEGIN
 SELECT * INTO STRICT settings FROM private.retention_settings;
 IF NOT settings.enabled THEN RETURN jsonb_build_object('dryRun',true,'count',(SELECT count(*) FROM public.conversations WHERE closed_at<now()-make_interval(days=>settings.days))); END IF;
 DELETE FROM public.conversations WHERE closed_at<now()-make_interval(days=>settings.days); GET DIAGNOSTICS removed=ROW_COUNT;
 INSERT INTO private.business_audit(action,reason,details) VALUES('retention_purge','Previously enabled retention schedule',jsonb_build_object('removed',removed));
 RETURN jsonb_build_object('dryRun',false,'removed',removed);
END $function$

CREATE OR REPLACE FUNCTION private.order_customer_names(p_order_ids uuid[])
 RETURNS TABLE(order_id uuid, customer_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE caller uuid := auth.uid();
BEGIN
  IF caller IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=caller AND NOT p.suspended) THEN
    RAISE EXCEPTION 'An active signed-in account is required' USING ERRCODE='42501';
  END IF;
  IF cardinality(p_order_ids)>200 THEN RAISE EXCEPTION 'Request at most 200 orders'; END IF;
  RETURN QUERY SELECT o.id, COALESCE(NULLIF(btrim(p.name),''),NULLIF(btrim(o.guest_name),''),'Guest')
  FROM public.orders o LEFT JOIN public.profiles p ON p.id=o.customer_id
  WHERE o.id=ANY(p_order_ids) AND (
    o.customer_id=caller OR private.is_admin() OR EXISTS(
      SELECT 1 FROM public.order_suborders s JOIN public.vendors v ON v.id=s.vendor_id
      JOIN public.profiles owner_profile ON owner_profile.id=v.owner_id
      WHERE s.order_id=o.id AND v.owner_id=caller AND v.status='approved'
        AND owner_profile.role='vendor' AND NOT owner_profile.suspended
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.reject_inactive_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p public.profiles%rowtype;
BEGIN
 IF auth.uid() IS NOT NULL THEN
  SELECT * INTO p FROM public.profiles WHERE id=auth.uid() FOR SHARE;
  IF NOT FOUND OR p.suspended OR p.deleted_at IS NOT NULL OR NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $function$

CREATE OR REPLACE FUNCTION private.require_fulfilment_on_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_TABLE_NAME='orders' THEN
  IF NEW.customer_id IS NOT NULL THEN
   PERFORM 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=NEW.customer_id AND NOT p.suspended AND p.deleted_at IS NULL FOR SHARE OF p;
   IF NOT FOUND THEN RAISE EXCEPTION 'Active customer account required'; END IF;
  END IF;
 ELSE
  PERFORM 1 FROM public.vendors v JOIN public.profiles p ON p.id=v.owner_id JOIN auth.users u ON u.id=p.id
  WHERE v.id=NEW.vendor_id AND v.status='approved' AND v.archived_at IS NULL AND NOT p.suspended AND p.deleted_at IS NULL FOR SHARE OF v,p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active approved vendor required for fulfilment'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.snapshot_paid_commission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='UPDATE' AND OLD.commission_amount IS NOT NULL AND (NEW.commission_amount IS DISTINCT FROM OLD.commission_amount
  OR NEW.commission_rate_snapshot IS DISTINCT FROM OLD.commission_rate_snapshot OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
  OR NEW.paid_at IS DISTINCT FROM OLD.paid_at OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id OR NEW.payment_status IS DISTINCT FROM OLD.payment_status) THEN RAISE EXCEPTION 'Paid financial snapshots are immutable'; END IF;
 IF TG_OP='UPDATE' AND OLD.payment_status IS DISTINCT FROM 'paid' AND NEW.payment_status='paid' THEN
  SELECT commission_rate,name INTO NEW.commission_rate_snapshot,NEW.vendor_name_snapshot FROM public.vendors WHERE id=NEW.vendor_id FOR SHARE;
  NEW.commission_amount:=round(NEW.subtotal*NEW.commission_rate_snapshot,2); NEW.paid_at:=clock_timestamp(); NEW.commission_evidence:='captured at verified paid transition';
 ELSIF TG_OP='INSERT' AND NEW.payment_status='paid' THEN RAISE EXCEPTION 'Create unpaid suborders; confirmation must perform the paid transition';
 ELSIF TG_OP='UPDATE' AND OLD.commission_amount IS NOT NULL AND (NEW.commission_amount IS DISTINCT FROM OLD.commission_amount
  OR NEW.commission_rate_snapshot IS DISTINCT FROM OLD.commission_rate_snapshot OR NEW.subtotal IS DISTINCT FROM OLD.subtotal
  OR NEW.paid_at IS DISTINCT FROM OLD.paid_at OR NEW.vendor_id IS DISTINCT FROM OLD.vendor_id) THEN RAISE EXCEPTION 'Paid financial snapshots are immutable'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.admin_allocate_payout(p_vendor_id uuid, p_suborder_ids uuid[], p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ledger jsonb; policy text; payout uuid; amount numeric; count_rows integer;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF p_request_id IS NULL OR coalesce(cardinality(p_suborder_ids),0)=0 THEN RAISE EXCEPTION 'Selection and request ID required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('officebites-payout'));
 SELECT id INTO payout FROM public.vendor_payouts WHERE request_id=p_request_id;
 IF FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM public.vendor_payouts WHERE id=payout AND vendor_id=p_vendor_id) THEN RAISE EXCEPTION 'Request ID conflict'; END IF;
  IF (SELECT array_agg(suborder_id ORDER BY suborder_id) FROM public.payout_allocations WHERE payout_id=payout) IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(p_suborder_ids) x) THEN RAISE EXCEPTION 'Request ID selection conflict'; END IF;
  RETURN to_jsonb((SELECT p FROM public.vendor_payouts p WHERE id=payout));
 END IF;
 PERFORM 1 FROM public.orders WHERE id IN(SELECT order_id FROM public.order_suborders WHERE id=ANY(p_suborder_ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM private.finance_settings FOR UPDATE;
 ledger:=public.get_payout_ledger(p_vendor_id); policy:=ledger->>'policy';
 IF policy IS NULL THEN RAISE EXCEPTION 'Approve processor-fee policy first'; END IF;
 SELECT count(*),sum(payable) INTO count_rows,amount FROM jsonb_to_recordset(ledger->'eligible') AS e(suborder_id uuid,payable numeric) WHERE suborder_id=ANY(p_suborder_ids) AND payable IS NOT NULL AND payable>=0;
 IF count_rows<>cardinality(p_suborder_ids) THEN RAISE EXCEPTION 'Selection includes unpaid, test, incomplete, unresolved or allocated records'; END IF;
 INSERT INTO public.vendor_payouts(vendor_id,request_id,fee_policy,amount,created_by) VALUES(p_vendor_id,p_request_id,policy,amount,auth.uid()) RETURNING id INTO payout;
 INSERT INTO public.payout_allocations(payout_id,suborder_id,gross,commission,processor_fee,payable)
  SELECT payout,e.suborder_id,e.gross,e.commission,CASE WHEN policy='vendor_proportional' THEN e.processor_fee ELSE 0 END,e.payable FROM jsonb_to_recordset(ledger->'eligible') AS e(suborder_id uuid,gross numeric,commission numeric,processor_fee numeric,payable numeric) WHERE suborder_id=ANY(p_suborder_ids);
 INSERT INTO private.business_audit(actor_id,action,record_id,reason) VALUES(auth.uid(),'allocate_payout',payout,'Completed paid business suborders; no transfer');
 RETURN to_jsonb((SELECT p FROM public.vendor_payouts p WHERE id=payout));
END $function$

CREATE OR REPLACE FUNCTION public.admin_classify_test_order(p_order_id uuid, p_reason text, p_expected_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF length(btrim(coalesce(p_reason,'')))<10 THEN RAISE EXCEPTION 'Review evidence and give a reason'; END IF;
 PERFORM 1 FROM public.orders WHERE id=p_order_id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.payout_allocations a JOIN public.order_suborders s ON s.id=a.suborder_id WHERE s.order_id=p_order_id AND a.released_at IS NULL) THEN RAISE EXCEPTION 'Reconcile payout allocations before classification'; END IF;
 UPDATE public.orders SET is_test=true,classification_version=classification_version+1 WHERE id=p_order_id AND classification_version=p_expected_version AND NOT is_test;
 IF NOT FOUND THEN RAISE EXCEPTION 'Classification changed; refresh preview'; END IF;
 INSERT INTO private.business_audit(actor_id,action,record_id,reason) VALUES(auth.uid(),'classify_test_order',p_order_id,p_reason);
 RETURN public.admin_preview_test_order(p_order_id);
END $function$

CREATE OR REPLACE FUNCTION public.admin_configure_retention(p_days integer, p_schedule text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF p_schedule IS NULL OR p_schedule !~ '^[0-9*/,-]+ [0-9*/,-]+ [0-9*/,-]+ [0-9*/,-]+ [0-9*/,-]+$' THEN RAISE EXCEPTION 'Five-field UTC cron schedule required'; END IF;
 UPDATE private.retention_settings SET days=p_days,schedule=p_schedule,enabled=false;
 IF to_regclass('cron.job') IS NOT NULL THEN
  EXECUTE 'SELECT cron.alter_job($1,schedule:=$2,active:=false)' USING (SELECT job_id FROM private.retention_settings),p_schedule;
 END IF;
 INSERT INTO private.business_audit(actor_id,action,reason,details) VALUES(auth.uid(),'configure_retention','Dry-run scheduling only',jsonb_build_object('days',p_days,'schedule',p_schedule));
END $function$

CREATE OR REPLACE FUNCTION public.admin_reconcile_payout(p_payout_id uuid, p_status text, p_reference text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF p_status IS NULL OR p_status NOT IN('paid','void') OR length(btrim(coalesce(p_reference,'')))<5 THEN RAISE EXCEPTION 'External transfer reference or void reason required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('officebites-payout'));
 UPDATE public.vendor_payouts SET status=p_status,reference=p_reference,reconciled_at=now() WHERE id=p_payout_id AND status='allocated';
 IF NOT FOUND THEN RAISE EXCEPTION 'Only allocated payouts may be reconciled'; END IF;
 IF p_status='void' THEN UPDATE public.payout_allocations SET released_at=now() WHERE payout_id=p_payout_id; END IF;
 INSERT INTO private.business_audit(actor_id,action,record_id,reason,details) VALUES(auth.uid(),'reconcile_payout',p_payout_id,p_reference,jsonb_build_object('status',p_status));
END $function$

CREATE OR REPLACE FUNCTION public.admin_record_historical_commission(p_suborder_id uuid, p_rate numeric, p_evidence text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 IF p_rate IS NULL OR p_rate<0 OR p_rate>1 OR length(btrim(coalesce(p_evidence,'')))<10 THEN RAISE EXCEPTION 'Rate and historical evidence required'; END IF;
 UPDATE public.order_suborders SET commission_rate_snapshot=p_rate,commission_amount=round(subtotal*p_rate,2),commission_evidence=p_evidence
  WHERE id=p_suborder_id AND payment_status='paid' AND commission_amount IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Only unresolved historical paid records may be backfilled'; END IF;
 INSERT INTO private.business_audit(actor_id,action,record_id,reason,details) VALUES(auth.uid(),'historical_commission',p_suborder_id,p_evidence,jsonb_build_object('rate',p_rate));
END $function$

CREATE OR REPLACE FUNCTION public.admin_reply_support_ticket(p_ticket_id uuid, p_body text, p_internal boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_message_id uuid;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 if (select auth.uid()) is null or not coalesce((select private.is_admin()),false) then raise exception 'forbidden'; end if;
 if p_ticket_id is null or not exists(select 1 from public.support_tickets where id=p_ticket_id) then raise exception 'ticket not found'; end if;
 if length(btrim(coalesce(p_body,'')))<1 or length(btrim(p_body))>5000 then raise exception 'message must be between 1 and 5000 characters'; end if;
 insert into public.support_ticket_messages(ticket_id,sender_id,sender_role,body,internal) values(p_ticket_id,(select auth.uid()),'support',btrim(p_body),coalesce(p_internal,false)) returning id into v_message_id;
 update public.support_tickets set first_response_at=case when not coalesce(p_internal,false) then coalesce(first_response_at,now()) else first_response_at end,status=case when not coalesce(p_internal,false) and status='open'::public.support_status then 'waiting_customer'::public.support_status else status end,updated_at=now() where id=p_ticket_id;
 return v_message_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_fee_policy(p_policy text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 IF NOT private.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('officebites-payout'));
 IF p_policy IS NULL OR p_policy NOT IN('platform_absorbs','vendor_proportional') OR length(btrim(coalesce(p_reason,'')))<10 THEN RAISE EXCEPTION 'Policy and decision reason required'; END IF;
 IF EXISTS(SELECT 1 FROM public.vendor_payouts WHERE status='allocated') THEN RAISE EXCEPTION 'Reconcile allocations before changing policy'; END IF;
 UPDATE private.finance_settings SET fee_policy=p_policy,updated_at=now(),updated_by=auth.uid();
 INSERT INTO private.business_audit(actor_id,action,reason,details) VALUES(auth.uid(),'fee_policy',p_reason,jsonb_build_object('policy',p_policy));
END $function$

CREATE OR REPLACE FUNCTION public.admin_update_support_ticket(p_ticket_id uuid, p_status support_status DEFAULT NULL::support_status, p_priority support_priority DEFAULT NULL::support_priority, p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_ticket public.support_tickets%rowtype;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 if (select auth.uid()) is null or not coalesce((select private.is_admin()),false) then raise exception 'forbidden'; end if;
 update public.support_tickets set status=coalesce(p_status,status),priority=coalesce(p_priority,priority),assigned_to=coalesce(p_assigned_to,assigned_to),resolved_at=case when p_status in ('resolved'::public.support_status,'closed'::public.support_status) then coalesce(resolved_at,now()) when p_status is not null then null else resolved_at end,updated_at=now() where id=p_ticket_id returning * into v_ticket;
 if not found then raise exception 'ticket not found'; end if;
 return jsonb_build_object('id',v_ticket.id,'ticketNumber',v_ticket.ticket_number,'status',v_ticket.status,'priority',v_ticket.priority,'assignedTo',v_ticket.assigned_to,'firstResponseAt',v_ticket.first_response_at,'resolvedAt',v_ticket.resolved_at,'updatedAt',v_ticket.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.admin_verify_payment(p_order_id uuid, p_approve boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order orders;
  v_new_status text;
  v_vendor_id uuid;
  v_vendor_name text;
  v_customer_name text;
  v_items text;
  v_subtotal numeric;
  v_customer_id uuid;
  v_ticket text;
  v_delivery_date date;
  v_delivery_location text;
  v_notify_errors jsonb := '[]'::jsonb;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
  if not private.is_admin() then
    raise exception 'Not authorized: admin access required';
  end if;

  select * into v_order from orders where id = p_order_id for update;
  if v_order.id is null then
    raise exception 'Order not found';
  end if;

  if v_order.status not in ('payment_submitted', 'pending_payment') then
    raise exception 'Order is not awaiting payment review (current status: %)', v_order.status;
  end if;

  v_new_status := case when p_approve then 'confirmed' else 'cancelled' end;
  v_customer_id := v_order.customer_id;
  v_ticket := v_order.ticket_number;
  v_delivery_date := v_order.delivery_date;
  v_delivery_location := v_order.delivery_location;

  select coalesce(p.name, v_order.guest_name, 'Guest')
    into v_customer_name
  from (select 1) x
  left join profiles p on p.id = v_order.customer_id;

  update orders set status = v_new_status::order_status where id = p_order_id;

  update order_suborders
    set status = v_new_status::order_status,
        payment_status = case when p_approve then 'paid'::payment_status else 'unpaid'::payment_status end
    where order_id = p_order_id;

  if v_customer_id is not null then
    insert into notifications (user_id, type, title, body)
    values (
      v_customer_id,
      case when p_approve then 'payment_verified' else 'payment_rejected' end,
      case when p_approve then 'Payment verified' else 'Payment rejected' end,
      case when p_approve
        then format('Your payment for %s has been verified — your order is confirmed.', v_ticket)
        else format('We could not verify the payment for %s. Please upload valid proof or contact support.', v_ticket)
      end
    );
  end if;

  if p_approve then
    for v_vendor_id, v_vendor_name, v_subtotal in
      select so.vendor_id, v.name, so.subtotal
      from order_suborders so
      join vendors v on v.id = so.vendor_id
      where so.order_id = p_order_id
    loop
      select coalesce(string_agg(format('%s × %s', oi.qty, oi.meal_name), ', ' order by oi.id), 'No items recorded')
        into v_items
      from order_items oi
      join order_suborders so on so.id = oi.suborder_id
      where so.order_id = p_order_id and so.vendor_id = v_vendor_id;

      for v_customer_id in
        select p.id
        from profiles p
        where p.vendor_id = v_vendor_id and p.role = 'vendor'
      loop
        insert into notifications (user_id, type, title, body)
        values (
          v_customer_id,
          'new_order',
          format('New order %s', v_ticket),
          format(
            'Customer: %s | Items: %s | Vendor subtotal: R%s | Delivery: %s%s',
            v_customer_name,
            v_items,
            to_char(coalesce(v_subtotal, 0), 'FM999999990.00'),
            coalesce(to_char(v_delivery_date, 'DD Mon YYYY'), 'Not specified'),
            case when nullif(trim(v_delivery_location), '') is not null
              then format(' | Location: %s', v_delivery_location)
              else '' end
          )
        );
      end loop;
    end loop;
  end if;

  return jsonb_build_object(
    'success', true,
    'status', v_new_status,
    'notify_errors', v_notify_errors
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.become_vendor(p_business_name text, p_business_category text, p_building text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 current_user_id uuid := auth.uid(); current_profile public.profiles%rowtype; existing_vendor public.vendors%rowtype; new_vendor public.vendors%rowtype;
 clean_name text:=nullif(trim(p_business_name),''); clean_category text:=nullif(trim(p_business_category),''); clean_building text:=nullif(trim(p_building),'');
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
 if current_user_id is null then raise exception 'You must be signed in to become a vendor'; end if;
 if clean_name is null then raise exception 'Business name is required'; end if;
 if clean_category is null then raise exception 'Business category is required'; end if;
 select * into current_profile from public.profiles where id=current_user_id for update;
 if not found then raise exception 'OfficeBites profile not found'; end if;
 if current_profile.role::text='admin' then raise exception 'Admin accounts cannot be converted to vendor accounts'; end if;
 if current_profile.vendor_id is not null then
  select * into existing_vendor from public.vendors where id=current_profile.vendor_id;
  if found then return jsonb_build_object('vendor_id',existing_vendor.id,'status',existing_vendor.status,'already_vendor',true); end if;
  raise exception 'Profile has an invalid vendor link';
 end if;
 select * into existing_vendor from public.vendors where owner_id=current_user_id order by created_at asc limit 1;
 if found then
  update public.profiles set role='vendor',vendor_id=existing_vendor.id,building=coalesce(clean_building,building) where id=current_user_id;
  return jsonb_build_object('vendor_id',existing_vendor.id,'status',existing_vendor.status,'already_vendor',true);
 end if;
 insert into public.vendors(owner_id,name,category,building,status,email) values(current_user_id,clean_name,clean_category,clean_building,'pending',current_profile.email) returning * into new_vendor;
 update public.profiles set role='vendor',vendor_id=new_vendor.id,building=coalesce(clean_building,building) where id=current_user_id;
 return jsonb_build_object('vendor_id',new_vendor.id,'status',new_vendor.status,'already_vendor',false);
end $function$

CREATE OR REPLACE FUNCTION public.complete_account_removal(p_actor uuid, p_job_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE job private.account_removal_jobs%rowtype;
BEGIN
 IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server only' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT job FROM private.account_removal_jobs WHERE id=p_job_id AND actor_id=p_actor FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=p_actor AND p.role='admin' AND NOT p.suspended AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Admin required'; END IF;
 IF EXISTS(SELECT 1 FROM auth.users WHERE id=job.target_user_id) THEN RAISE EXCEPTION 'Auth identity still exists'; END IF;
 IF EXISTS(SELECT 1 FROM storage.objects o JOIN jsonb_to_recordset(job.manifest->'storage') x(bucket text,name text) ON o.bucket_id=x.bucket AND o.name=x.name) THEN RAISE EXCEPTION 'Storage cleanup incomplete'; END IF;
 IF EXISTS(SELECT 1 FROM storage.objects WHERE owner_id=job.target_user_id::text OR owner=job.target_user_id OR(bucket_id IN('meal-images','vendor-images') AND split_part(name,'/',1) IN(SELECT id::text FROM public.vendors WHERE owner_id=job.target_user_id))) THEN RAISE EXCEPTION 'New Storage dependencies found; retry cleanup'; END IF;
 UPDATE private.account_removal_jobs SET state='complete',completed_at=now() WHERE id=job.id;
 INSERT INTO private.business_audit(actor_id,action,record_id,reason) VALUES(p_actor,'complete_account_removal',job.target_user_id,'Auth deletion and Storage cleanup verified');
END $function$

CREATE OR REPLACE FUNCTION public.confirm_payfast_payment(p_order_id uuid, p_pf_payment_id text, p_m_payment_id text, p_amount_gross numeric, p_payment_status text, p_raw_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_order public.orders%ROWTYPE;
  v_log public.payfast_itn_log%ROWTYPE;
  v_sub record;
  v_fee numeric := 0;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_order FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF v_order.payment_method<>'payfast' THEN RAISE EXCEPTION 'This is not a PayFast order'; END IF;
  IF nullif(trim(p_pf_payment_id),'') IS NULL OR p_m_payment_id IS DISTINCT FROM v_order.ticket_number THEN
    RAISE EXCEPTION 'Invalid PayFast payment reference';
  END IF;
  IF p_payment_status IS NULL THEN RAISE EXCEPTION 'Payment status is required'; END IF;
  IF p_amount_gross IS NULL OR p_amount_gross<>v_order.total THEN RAISE EXCEPTION 'PayFast amount does not match the order total'; END IF;
  SELECT * INTO v_log FROM public.payfast_itn_log WHERE pf_payment_id=p_pf_payment_id FOR UPDATE;
  IF FOUND THEN
    IF v_log.order_id IS DISTINCT FROM p_order_id THEN RAISE EXCEPTION 'Payment ID belongs to another order'; END IF;
    IF v_log.payment_status='COMPLETE' THEN RETURN jsonb_build_object('duplicate',true,'applied',false); END IF;
  END IF;
  IF coalesce(p_raw_payload->>'amount_fee','') ~ '^-?[0-9]+([.][0-9]+)?$' THEN
    v_fee:=abs((p_raw_payload->>'amount_fee')::numeric);
  END IF;
  INSERT INTO public.payfast_itn_log(pf_payment_id,order_id,m_payment_id,amount_gross,payment_status,raw_payload,processor_fee)
    VALUES(p_pf_payment_id,p_order_id,p_m_payment_id,p_amount_gross,p_payment_status,coalesce(p_raw_payload,'{}'::jsonb),v_fee)
    ON CONFLICT(pf_payment_id) DO UPDATE SET payment_status=excluded.payment_status,
      raw_payload=excluded.raw_payload,amount_gross=excluded.amount_gross,
      processor_fee=excluded.processor_fee,processed_at=now()
      WHERE public.payfast_itn_log.order_id=excluded.order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment ID belongs to another order'; END IF;
  IF p_payment_status<>'COMPLETE' THEN
    RETURN jsonb_build_object('duplicate',false,'applied',false,'reason','not_complete');
  END IF;
  IF v_order.status NOT IN ('pending_payment','payment_submitted') THEN
    RETURN jsonb_build_object('duplicate',false,'applied',false,'reason','not_eligible','current_status',v_order.status);
  END IF;
  UPDATE public.orders SET status='confirmed' WHERE id=p_order_id;
  UPDATE public.order_suborders SET status='confirmed',payment_status='paid' WHERE order_id=p_order_id;
  IF v_order.customer_id IS NOT NULL THEN
    INSERT INTO public.notifications(user_id,type,title,body,action_url)
      VALUES(v_order.customer_id,'payment_confirmed','Payment confirmed',
        format('Your payment for %s has been verified.',v_order.ticket_number),'/orders/'||p_order_id::text);
  END IF;
  FOR v_sub IN SELECT so.subtotal,v.owner_id,v.name FROM public.order_suborders so
    JOIN public.vendors v ON v.id=so.vendor_id WHERE so.order_id=p_order_id
  LOOP
    IF v_sub.owner_id IS NOT NULL THEN
      INSERT INTO public.notifications(user_id,type,title,body,action_url)
        VALUES(v_sub.owner_id,'new_order','New paid order '||v_order.ticket_number,
          format('%s: R%s for %s',v_sub.name,v_sub.subtotal,to_char(v_order.delivery_date,'DD Mon YYYY')),'/vendor/orders');
    END IF;
  END LOOP;
  RETURN jsonb_build_object('duplicate',false,'applied',true,
    'order',(SELECT public.order_to_json(o) FROM public.orders o WHERE o.id=p_order_id));
END $function$

CREATE OR REPLACE FUNCTION public.create_order_from_cart(p_customer_id uuid, p_guest_name text, p_guest_contact text, p_guest_email text, p_delivery_date date, p_delivery_location text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_customer_id uuid := auth.uid();
  v_order_id uuid := gen_random_uuid();
  v_ticket text;
  v_total numeric(10,2);
  v_requested_count integer;
  v_priced_count integer;
  v_vendor_id uuid;
  v_suborder_id uuid;
BEGIN IF auth.uid() IS NOT NULL AND NOT private.active_account() THEN RAISE EXCEPTION 'Active account required' USING ERRCODE='42501'; END IF;
  if p_customer_id is not null and p_customer_id is distinct from auth.uid() then
    raise exception 'Customer identity does not match the current session';
  end if;

  if v_customer_id is not null and exists(select 1 from public.profiles where id=v_customer_id and suspended) then
    raise exception 'This account is suspended';
  end if;

  if v_customer_id is not null then
    p_guest_name := null;
    p_guest_contact := null;
    p_guest_email := null;
  else
    if nullif(trim(p_guest_name), '') is null then
      raise exception 'Guest name is required';
    end if;
    if nullif(trim(p_guest_contact), '') is null then
      raise exception 'Guest mobile number is required';
    end if;
  end if;

  if p_delivery_date is null then
    raise exception 'Delivery date is required';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Your cart is empty';
  end if;

  if nullif(trim(p_delivery_location), '') is null then raise exception 'Delivery location is required'; end if;
  if clock_timestamp() >= (((p_delivery_date - 1)::timestamp + interval '19 hours') at time zone 'Africa/Johannesburg') then
    raise exception 'Ordering has closed for this delivery date';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items) x
    where jsonb_typeof(x) <> 'object' or coalesce(x->>'mealId','') = ''
      or coalesce(x->>'qty','') !~ '^[1-9][0-9]*$') then
    raise exception 'Every cart item requires a meal ID and positive whole-number quantity';
  end if;
  if exists(select 1 from jsonb_array_elements(p_items) x where (x->>'qty')::numeric > 2147483647) then
    raise exception 'Cart quantity is too large';
  end if;
  if (select count(*) <> count(distinct x->>'mealId') from jsonb_array_elements(p_items) x) then
    raise exception 'Combine duplicate meals into one cart item';
  end if;
  perform m.id from jsonb_array_elements(p_items) x
    join public.meals m on m.id=(x->>'mealId')::uuid
    join public.vendors v on v.id=m.vendor_id for share of m,v;

  select count(distinct (x->>'mealId')::uuid)
    into v_requested_count
  from jsonb_array_elements(p_items) x
  where nullif(x->>'mealId', '') is not null;

  if v_requested_count = 0 then
    raise exception 'Your cart contains no valid meals';
  end if;

  select count(distinct m.id)
    into v_priced_count
  from jsonb_array_elements(p_items) x
  join meals m on m.id = (x->>'mealId')::uuid
  join vendors v on v.id = m.vendor_id
  where m.available = true
    and v.status = 'approved'
    and (x->>'qty')::integer > 0
    and (m.available_days is null or cardinality(m.available_days)=0
      or extract(dow from p_delivery_date)::integer=any(m.available_days));

  if v_priced_count <> v_requested_count then
    raise exception 'One or more meals in your cart are no longer available';
  end if;

  select round(sum(m.price * (x->>'qty')::integer), 2)
    into v_total
  from jsonb_array_elements(p_items) x
  join meals m on m.id = (x->>'mealId')::uuid
  join vendors v on v.id = m.vendor_id
  where m.available = true and v.status = 'approved';

  v_ticket := 'OB-' || upper(substr(md5(v_order_id::text || clock_timestamp()::text), 1, 6));

  insert into orders (
    id, ticket_number, customer_id, guest_name, guest_contact, guest_email,
    delivery_date, delivery_location, status, total
  )
  values (
    v_order_id,
    v_ticket,
    v_customer_id,
    case when v_customer_id is null then trim(p_guest_name) else null end,
    case when v_customer_id is null then trim(p_guest_contact) else null end,
    case when v_customer_id is null then nullif(trim(p_guest_email), '') else null end,
    p_delivery_date,
    nullif(trim(p_delivery_location), ''),
    'pending_payment',
    v_total
  );

  for v_vendor_id in
    select m.vendor_id
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    join vendors v on v.id = m.vendor_id
    where m.available = true and v.status = 'approved'
    group by m.vendor_id
  loop
    insert into order_suborders (order_id, vendor_id, status, payment_status, subtotal)
    select
      v_order_id,
      v_vendor_id,
      'pending_payment',
      'unpaid',
      round(sum(m.price * (x->>'qty')::integer), 2)
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    where m.vendor_id = v_vendor_id
    returning id into v_suborder_id;

    insert into order_items (suborder_id, meal_id, meal_name, qty, price)
    select
      v_suborder_id,
      m.id,
      m.name,
      (x->>'qty')::integer,
      m.price
    from jsonb_array_elements(p_items) x
    join meals m on m.id = (x->>'mealId')::uuid
    where m.vendor_id = v_vendor_id;
  end loop;

  return order_to_json((select o from orders o where o.id = v_order_id));
end;
$function$

CREATE OR REPLACE FUNCTION public.create_support_ticket(p_subject text, p_category text, p_body text, p_requester_name text, p_requester_email text, p_requester_contact text, p_order_id uuid DEFAULT NULL::uuid, p_meta jsonb DEFAULT '{}'::jsonb, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE caller uuid:=auth.uid(); ticket public.support_tickets%rowtype; message public.support_ticket_messages%rowtype;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'Please sign in before contacting support' USING ERRCODE='42501'; END IF;
  IF length(btrim(coalesce(p_subject,''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Subject must be between 1 and 200 characters'; END IF;
  IF length(btrim(coalesce(p_body,''))) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Message must be between 1 and 5000 characters'; END IF;
  IF p_attachment_path IS NOT NULL AND split_part(p_attachment_path,'/',1)<>caller::text THEN
    RAISE EXCEPTION 'Attachment must belong to the requester' USING ERRCODE='42501';
  END IF;
  INSERT INTO public.support_tickets(requester_id,requester_name,requester_email,requester_contact,subject,category,order_id,meta,attachment_url)
  VALUES(caller,coalesce(nullif(btrim(p_requester_name),''),'Customer'),nullif(btrim(p_requester_email),''),nullif(btrim(p_requester_contact),''),btrim(p_subject),p_category,p_order_id,coalesce(p_meta,'{}'::jsonb),p_attachment_path)
  RETURNING * INTO ticket;
  INSERT INTO public.support_ticket_messages(ticket_id,sender_id,sender_role,body,internal)
  VALUES(ticket.id,caller,'customer',btrim(p_body),false) RETURNING * INTO message;
  RETURN to_jsonb(ticket) || jsonb_build_object('support_ticket_messages',jsonb_build_array(to_jsonb(message)));
END;
$function$

